import React from 'react';
import { GameMode } from '../types';

interface ModeSelectorProps {
  onSelect: (mode: GameMode) => void;
}

export const ModeSelector: React.FC<ModeSelectorProps> = ({ onSelect }) => {
  const modes: { value: GameMode; label: string; description: string }[] = [
    {
      value: 'normal',
      label: 'Normal Mode',
      description: 'See 5 traits → Guess the job/movie/game'
    },
    {
      value: 'hard',
      label: 'Hard Mode',
      description: 'See the job/movie/game → Guess all 5 traits'
    }
  ];

  return (
    <div className="w-full max-w-2xl mx-auto p-6 bg-white rounded-lg shadow-lg">
      <h2 className="text-2xl font-bold mb-6 text-center">Select Game Mode</h2>
      
      <div className="space-y-4">
        {modes.map((mode) => (
          <button
            key={mode.value}
            onClick={() => onSelect(mode.value)}
            className="w-full p-6 text-left bg-gradient-to-r from-purple-50 to-pink-50 hover:from-purple-100 hover:to-pink-100 rounded-lg transition-all"
          >
            <h3 className="text-lg font-bold mb-2">{mode.label}</h3>
            <p className="text-gray-600">{mode.description}</p>
          </button>
        ))}
      </div>
    </div>
  );
};
